const evaluation=$context.$nodes.XDX_EVALUATE_CONTROL.$output.result;
const state=JSON.parse(JSON.stringify(evaluation.state));
state.nextOperation=evaluation.operation;
state.response={message:evaluation.reason||'Describe a supplier search or draft change.'};
['kind','mode','requestId','revision','payload','source','confirmCommand','attempts','supplier','address','assignments','writeCount','writeOrder','site','SupplierSiteId','continuationCommand'].forEach(function(k){if(Object.prototype.hasOwnProperty.call(evaluation,k))state.response[k]=evaluation[k];});
if(Array.isArray(state.response.attempts))state.response.attempts=state.response.attempts.map(function(attempt){const shown=JSON.parse(JSON.stringify(attempt));if(shown.kind==='supplier')delete shown.sourceSupplierId;return shown;});
if(evaluation.operation==='create_supplier')state.dispatch=JSON.parse(JSON.stringify(evaluation.attempt));
return {operation:evaluation.operation,state:state};
